        public void Walk(Point2 point){var v=View;var path=new NavigationGrid(v.Geometry[v.Actor.Scene]).FindPath(v.Actor.Position,point,true);Require(path.Length>0,"actual R5 safe path missing: "+v.Actor.Scene);Done(Service.TraverseAsync(path));}
        public void Spot(string spot)=>Walk(View.Geometry[View.Actor.Scene].Spots.Single(x=>x.Id==spot).Stand);
        public void Exit(string scene){var p=View.Geometry[View.Actor.Scene].Ports.Single(x=>x.TargetScene==scene);Walk(p.Stand);Success(Done(Service.EnterPortAsync(p.Id)));}
        public void Goto(string destination)
        {
            var v=View;var queue=new Queue<string>();queue.Enqueue(v.Actor.Scene);var previous=new Dictionary<string,string?>{{v.Actor.Scene,null}};
            while(queue.TryDequeue(out string? scene)){if(scene==destination)break;foreach(var p in v.Geometry[scene].Ports){if(Service.PortIssue(v.Snapshot,p) is not null||previous.ContainsKey(p.TargetScene))continue;previous.Add(p.TargetScene,scene);queue.Enqueue(p.TargetScene);}}
            Require(previous.ContainsKey(destination),"no currently permitted R5 path to "+destination);var steps=new List<string>();for(string? scene=destination;previous[scene!] is{} from;scene=from)steps.Add(scene!);steps.Reverse();foreach(string scene in steps)Exit(scene);
        }
